137	// manifestBrainWrite matches a write of the manifest back into the brain
138	// directory: a write-named helper taking the brain dir and the manifest name.
139	// It deliberately does not match a manifest packed into a bundle tar, which
140	// copies a freshly built value rather than rewriting live state.
141	var manifestBrainWrite = regexp.MustCompile(`(?i)write[A-Za-z]*\(\s*(outputDir|brainDir)\s*,\s*exportManifestFileName`)
142	
143	// Every file that rewrites the manifest into the brain directory gates on the
144	// strict reader.
145	//
146	// The tolerant reader exists for the ~280 call sites that only consume the
147	// manifest, but three writers used loadBrainManifest's strictness as their write
148	// guard and two of them are nowhere near writeBrainManifestAndReadme. Making the
149	// reader tolerant silently disarmed those two: the bytes they write are
150	// marshalled from a struct, so a field the reader dropped would be erased. This
151	// discovers writers by scanning, so a new one cannot quietly inherit the wrong
152	// reader.
153	func TestEveryManifestWriterGatesOnTheStrictReader(t *testing.T) {
154		t.Parallel()
155	
156		entries, err := os.ReadDir(".")
157		if err != nil {
158			t.Fatal(err)
159		}
160		writers := 0
161		for _, entry := range entries {
162			name := entry.Name()
163			if entry.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
164				continue
165			}
166			source, err := os.ReadFile(name)
167			if err != nil {
168				t.Fatal(err)
169			}
170			text := string(source)
171			if !manifestBrainWrite.MatchString(text) {
172				continue
173			}
174			writers++
175			if !strings.Contains(text, "loadBrainManifestForReplace") {
176				t.Errorf("%s rewrites the brain manifest but never calls loadBrainManifestForReplace; a writer "+
177					"gated on the tolerant loadBrainManifest erases fields another build wrote", name)
178			}
179		}
180		if writers < 3 {
181			t.Fatalf("found %d manifest writers, want at least the 3 known ones; the detection pattern has drifted", writers)
182		}
183	}
