248			t.Fatal(err)
249		}
250		if !bytes.Equal(before, after) {
251			t.Fatal("unknown fields were changed")
252		}
253		if _, err := base.SafeReadFile(path, base.MaxManifestBytes); err == nil {
254			t.Fatal("unrelated bounded reader lost its limit")
255		}
256		// Explicit forced-refresh cleanup shares the dedicated decoder, while still
257		// using the checked remover. This only removes synthetic test state.
258		removed, err := discardManifestThisBuildCannotRewrite(dir)
259		if err != nil || !removed {
