264	// TestWriterRefusalExplainsItselfInsteadOfSayingCorrupt pins COR-2162.
265	//
266	// A writer refusing an unknown field is correct: re-encoding from a struct
267	// that never saw the field would erase what another build recorded. What was
268	// wrong is how it read. "brain manifest cannot be parsed: memory_state_corrupt"
269	// describes damage, and the manifest is undamaged and fully readable — a
270	// reader on the same bytes succeeds. On a real machine that wording left a
271	// component failed for four days while nothing was broken.
272	func TestWriterRefusalExplainsItselfInsteadOfSayingCorrupt(t *testing.T) {
273		t.Parallel()
274		dir := t.TempDir()
275		path := filepath.Join(dir, "manifest.json")
276		// schema_version must be in range, or the version guards answer first and
277		// this test would pass without ever reaching the unknown-field path.
278		// The probe field must be one no release will ever claim. "suppressed_warnings"
279		// was a real candidate for the manifest and has since become a real field,
280		// which turned this guard red on the branch that added it -- the test was
281		// asserting "unknown" about a name the product was still free to take.
282		body := fmt.Sprintf(`{"schema_version":%d,"zz_field_no_release_will_define":["x"]}`, brainManifestSchemaVersion)
283		if err := os.WriteFile(path, []byte(body), 0o600); err != nil {
284			t.Fatal(err)
285		}
286	
287		open := func() *os.File {
288			f, err := os.Open(path)
289			if err != nil {
290				t.Fatal(err)
291			}
292			t.Cleanup(func() { _ = f.Close() })
293			return f
294		}
295	
296		// A reader is unaffected: the bytes are readable, which is the whole point.
297		if _, _, dropped, err := decodeBrainManifestFile(open(), true); err != nil {
298			t.Fatalf("a reader must still read this manifest, got: %v", err)
299		} else if !dropped {
300			t.Fatal("the reader should report that it dropped an unknown field")
301		}
302	
303		_, _, _, err := decodeBrainManifestFile(open(), false)
304		if err == nil {
305			t.Fatal("a writer must refuse rather than silently erase the unknown field")
306		}
307		msg := err.Error()
308		if !strings.Contains(msg, "zz_field_no_release_will_define") {
309			t.Errorf("refusal must name the field the reader has to act on: %v", err)
310		}
311		if !strings.Contains(msg, "NOT damaged") {
312			t.Errorf("refusal must say the manifest is not damaged: %v", err)
313		}
314		if strings.Contains(msg, "cannot be parsed") {
315			t.Errorf("refusal still claims the manifest cannot be parsed, but a reader just parsed it: %v", err)
316		}
317		// The code is part of the maintenance taxonomy and many consumers match on
318		// it, so improving the sentence must not retype the error.
319		if !strings.Contains(msg, brainstore.StateCorruptCode) {
320			t.Errorf("error code changed; that is a contract change, not a wording fix: %v", err)
321		}
322	}
