130	// The watch daemon's full refresh (consolidation) runs in the SAME unattended
131	// launchd tick as the delta: on the first tick, on every --consolidate-every
132	// elapsed tick, and immediately whenever the short-term buffer overflows.
133	// TestWatchTickSkipsTranscriptSweep alone over-claims coverage here -- it
134	// drives only the delta half. This drives watchDeterministicRefresh (the
135	// consolidation step itself, watch.go's steps.refresh) directly, after a real
136	// tick has already established the persistent brain, and proves it leaves a
137	// stale cached transcript alone too.
138	func TestWatchConsolidationRefreshSkipsTranscriptSweep(t *testing.T) {
139		opts, repoDir, storage, _ := watchCommandFixture(t)
140		// An empty, successful routed checkpoint catalog: the fixture's local git
141		// refs are unmocked, so every export phase falls through to routed
142		// discovery via the "entire" binary. Without this, the FIRST tick's export
143		// failure is silently papered over as "degraded, fall back to seed" (no
144		// manifest exists yet to make it fatal), while the SECOND direct refresh
145		// call below has a manifest by then and the identical failure turns fatal
146		// -- hiding what this test means to exercise behind an unrelated fixture gap.
147		opts.Runner.(*fakeCommandRunner).responses[fakeRoutedCheckpointListKey("entire", true)] = fakeCommandResponse{stdout: `[]`}
148	
149		// Establish the persistent brain the way the real daemon's first-ever tick
150		// does (the first refresh always runs).
