152			t.Fatalf("watch once: %v\n%s", err, out)
153		}
154	
155		sweepable := "sessions/main/stale.jsonl"
156		if err := writeTranscriptFile(storage.BrainDir, sweepable, []byte("stale")); err != nil {
157			t.Fatal(err)
158		}
159	
160		cmd := &cobra.Command{}
161		cmd.SetOut(io.Discard)
162		cmd.SetErr(io.Discard)
163		// true: this models the daemon's own tick (watch.go's watchStepsForRepo),
164		// which is unattended and always skips the sweep.
165		if err := watchDeterministicRefresh(context.Background(), cmd, opts, repoDir, true); err != nil {
166			t.Fatalf("watch consolidation refresh: %v", err)
167		}
168	
169		if _, err := os.Stat(filepath.Join(storage.BrainDir, filepath.FromSlash(sweepable))); err != nil {
170			t.Fatalf("watch consolidation refresh swept the transcript cache: %v", err)
171		}
172	}
