16	// ReadFile decodes the canonical manifest without a byte ceiling.
17	// It uses the same checked descriptor as bounded state readers, without needing
18	// the source repository or Git. encoding/json buffers a whole JSON value and
19	// the manifest is materialized in memory: this is NOT a bounded-memory reader.
20	// Rewinding this descriptor (never reopening the path) preserves schema-first
21	// checks and tolerant reads versus strict rewrites, including unknown fields.
22	func ReadFile(brainDir string, tolerateUnknown bool) (*Manifest, int, bool, bool, error) {
23		f, present, err := brainstore.OpenMemoryStateFileExpected(brainDir, FileName, "brain manifest", nil)
24		if err != nil {
25			return nil, 0, false, present, fmt.Errorf("read brain manifest: %w", err)
26		}
27		if !present {
28			return &Manifest{SchemaVersion: SchemaVersion}, 0, false, false, nil
29		}
30		defer f.Close()
31		manifest, version, dropped, err := DecodeFile(f, tolerateUnknown)
32		return manifest, version, dropped, true, err
33	}
34	
35	func decodePass(f *os.File, out any, strict bool) error {
36		if _, err := f.Seek(0, io.SeekStart); err != nil {
37			return err
38		}
39		decoder := json.NewDecoder(f)
40		if strict {
41			decoder.DisallowUnknownFields()
42		}
43		if err := decoder.Decode(out); err != nil {
44			return err
45		}
46		if err := decoder.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
47			return brainstore.ErrTrailingJSONData
48		}
49		return nil
50	}
51	
52	func DecodeFile(f *os.File, tolerateUnknown bool) (*Manifest, int, bool, error) {
53		var header struct {
54			SchemaVersion int `json:"schema_version"`
55		}
56		if err := decodePass(f, &header, false); err != nil {
57			return nil, 0, false, fmt.Errorf("parse brain manifest: %s: brain manifest cannot be parsed: %w", brainstore.StateCorruptCode, err)
58		}
59		version := header.SchemaVersion
60		if version > SchemaVersion {
61			return nil, version, false, fmt.Errorf("%s: brain manifest schema version %d is newer than supported version %d; upgrade entire-brain to read it", brainstore.UnsupportedVersionCode, version, SchemaVersion)
62		}
63		var manifest Manifest
64		err := decodePass(f, &manifest, true)
65		dropped := false
66		if tolerateUnknown && brainstore.IsUnknownFieldError(err) {
67			manifest = Manifest{}
68			err = decodePass(f, &manifest, false)
69			dropped = err == nil
70		}
71		if err != nil {
72			// An unknown field is not damage, and saying "cannot be parsed" sends
73			// the reader looking for corruption that is not there. The manifest is
74			// entirely readable; a WRITER is refusing it, because re-encoding from
75			// a struct that never saw the field would erase what another build
76			// recorded. Readers pass tolerateUnknown and are unaffected.
77			//
78			// Observed cost of the old wording: a component sat failed for four
79			// days reporting memory_state_corrupt, while the manifest was fine and
80			// the condition had already gone away.
81			//
82			// The error CODE stays memory_state_corrupt deliberately. It is part of
83			// the maintenance taxonomy with many consumers, so retyping this case
84			// is a contract change for a human to make, not a side effect of
85			// improving a sentence.
86			if !tolerateUnknown && brainstore.IsUnknownFieldError(err) {
87				return nil, version, false, fmt.Errorf(
88					"parse brain manifest: %s: brain manifest carries a field this build does not know (%w); "+
89						"the file is readable and is NOT damaged, but a writer will not rewrite it and silently drop that field. "+
90						"Use a build that knows the field, or let a read-only command run instead",
91					brainstore.StateCorruptCode, err)
92			}
93			return nil, version, false, fmt.Errorf("parse brain manifest: %s: brain manifest cannot be parsed: %w", brainstore.StateCorruptCode, err)
94		}
95		if version < MinSchemaVersion {
96			return nil, version, false, fmt.Errorf("%s: brain manifest declares schema version %d, older than the first supported version %d", brainstore.UnsupportedVersionCode, version, MinSchemaVersion)
97		}
98		Normalize(&manifest)
99		return &manifest, version, dropped, nil
100	}
101	
102	// Load reads the manifest for the callers that only consume it —
103	// status, doctor, the memory worker, distillation, search.
104	//
105	// It tolerates fields it does not declare. Manifest fields are added and retired
106	// without a schema bump (history_coverage.checkpointed_unexported_commits was
107	// retired at version 3), so every manifest written before such a change carries
108	// a field a later build has never heard of. Rejecting those bytes reported the
109	// whole brain as memory_state_corrupt: all sources off, no facts, and the memory
110	// worker failing on its retry loop indefinitely, for state that was merely
111	// written by a different build and is entirely readable.
112	//
113	// Writers must not be this forgiving — see LoadForReplace.
114	func Load(outputDir string) (*Manifest, error) {
115		manifest, _, err := Read(outputDir, true)
116		return manifest, err
117	}
118	
119	// LoadForReplace reads the manifest on behalf of a writer about to
120	// overwrite it, and refuses fields it cannot round-trip: re-encoding from a
121	// struct that never saw them erases what another build recorded. Availability is
122	// the reader's concern; not destroying state is this one's.
123	func LoadForReplace(outputDir string) (*Manifest, error) {
124		manifest, _, err := Read(outputDir, false)
125		// NOT isUnknownFieldError: that matches on a PREFIX, and by the time the
126		// error reaches here it has been wrapped ("parse brain manifest: ..."), so
127		// the prefix never matches and the remedy was silently never attached.
128		if IsRetiredFieldError(err) {
129			// Durable, and the bare decoder error says none of this. A field that
130			// was RETIRED without a schema bump leaves every manifest written by
131			// the older build unwritable by this one -- for ever, because nothing
132			// in the normal path rewrites it. On this machine that silently drove
133			// a two-hour relaunch chain per repository, with a live sleeping
134			// process per retry, and the worker log recorded only "prepass_failed".
135			return manifest, errors.New(RetiredFieldMessage(err))
136		}
137		return manifest, err
138	}
139	
140	// IsRetiredFieldError reports a manifest a writer cannot round-trip because
141	// it carries a field this build no longer declares.
142	//
143	// It is a DURABLE condition: no amount of retrying changes the bytes on disk,
144	// so a relaunch chain spends two hours and ends exactly where it started.
145	// retiredRemedy is the one wording, so the "already said it" check
146	// below cannot drift from the thing it is checking for.
147	// A func, not a const: the spelling depends on how the reader reached this
148	// binary, which is only knowable at call time.
149	func retiredRemedy() string {
150		return "; this manifest carries a field this build retired, so it cannot be rewritten without erasing what another build recorded -- rebuild it with `" + base.BrainInvocation(os.LookupEnv, "refresh") + " --force`"
151	}
152	
153	// RetiredFieldMessage states the failure AND what to do about it.
154	//
155	// The remedy has to be attached here rather than at the read, because the
156	// manifest is read through several paths and only some of them wrap the error.
157	// Measured: the delta-export path reported the bare decoder error, so the one
158	// line a reader actually saw named a JSON field and no action at all.
159	func RetiredFieldMessage(err error) string {
160		if err == nil {
161			return ""
162		}
163		msg := err.Error()
164		// Idempotent. LoadForReplace already attaches this remedy, and
165		// the worker then asks for the message again -- appending unconditionally
166		// printed the whole explanation TWICE. Caught by weakening: deleting this
167		// function's retired-field branch made the output better, which is only
168		// possible if the branch was doing harm.
169		if strings.Contains(msg, retiredRemedy()) {
170			return msg
171		}
172		return msg + retiredRemedy()
173	}
174	
175	func IsRetiredFieldError(err error) bool {
176		return brainstore.IsUnknownFieldError(err) || (err != nil &&
177			strings.Contains(err.Error(), brainstore.StateCorruptCode) &&
178			strings.Contains(err.Error(), "unknown field"))
179	}
180	
181	// Read also reports whether it dropped fields written by another
182	// build, so status and doctor can recommend a refresh instead of staying silent.
183	func Read(outputDir string, tolerateUnknownFields bool) (*Manifest, bool, error) {
184		manifest, _, dropped, _, err := ReadFile(outputDir, tolerateUnknownFields)
185		return manifest, dropped, err
186	}
187	
188	func Normalize(manifest *Manifest) {
189		if manifest.SchemaVersion == 0 {
190			manifest.SchemaVersion = 1
191		}
192		if manifest.Sources == nil {
193			manifest.Sources = &Sources{}
194		}
195		if manifest.Sources.Sessions == nil && (len(manifest.Sessions) > 0 || manifest.TranscriptMode != "" || manifest.CheckpointsScanned > 0) {
196			manifest.Sources.Sessions = SessionSourceFromExport(*manifest)
197		}
198	}
199	
200	func SessionSourceFromExport(manifest Manifest) *SessionSource {
201		return &SessionSource{
202			GeneratedAt:        manifest.GeneratedAt,
203			EntireCLIVersion:   manifest.EntireCLIVersion,
204			DefaultBranch:      manifest.DefaultBranch,
205			TranscriptMode:     manifest.TranscriptMode,
206			TranscriptStorage:  manifest.TranscriptStorage,
207			Scope:              manifest.Scope,
208			CheckpointLimit:    manifest.CheckpointLimit,
209			CheckpointsScanned: manifest.CheckpointsScanned,
210			OldestSessionAt:    OldestSessionAt(manifest.Sessions),
211			LatestCheckpointID: LatestCheckpointID(manifest.Sessions),
212			Branches:           append([]Branch(nil), manifest.Branches...),
213			Sessions:           append([]Session(nil), manifest.Sessions...),
214			Warnings:           append([]string(nil), manifest.Warnings...),
215		}
216	}
217	
218	func OldestSessionAt(sessions []Session) *time.Time {
219		var oldest time.Time
220		for _, session := range sessions {
221			if session.CreatedAt.IsZero() {
222				continue
223			}
224			if oldest.IsZero() || session.CreatedAt.Before(oldest) {
225				oldest = session.CreatedAt.UTC()
226			}
227		}
228		if oldest.IsZero() {
229			return nil
230		}
231		return &oldest
232	}
233	
234	func LatestCheckpointID(sessions []Session) string {
235		var latest Session
236		for _, session := range sessions {
237			if latest.SessionID == "" || shouldReplaceSession(latest, session) {
238				latest = session
239			}
240		}
241		return latest.LatestCheckpoint
242	}
243	
244	func shouldReplaceSession(current, candidate Session) bool {
245		if candidate.CreatedAt.After(current.CreatedAt) {
246			return true
247		}
248		if current.CreatedAt.Equal(candidate.CreatedAt) {
249			return candidate.LatestCheckpoint > current.LatestCheckpoint
250		}
251		return false
252	}
